begin;
create extension if not exists pgtap with schema extensions;
select plan(49);
insert into auth.users(id,email) values ('40000000-0000-0000-0000-000000000001','plan-owner@example.invalid'),('40000000-0000-0000-0000-000000000002','plan-worker@example.invalid'),('40000000-0000-0000-0000-000000000003','plan-outsider@example.invalid'),('40000000-0000-0000-0000-000000000004','plan-manager@example.invalid');
insert into public.teams(id,name,created_by) values ('40000000-0000-0000-0000-000000000010','Plan test','40000000-0000-0000-0000-000000000001'),('40000000-0000-0000-0000-000000000020','Other','40000000-0000-0000-0000-000000000003');
insert into public.team_members values ('40000000-0000-0000-0000-000000000010','40000000-0000-0000-0000-000000000001','owner'),('40000000-0000-0000-0000-000000000010','40000000-0000-0000-0000-000000000002','employee'),('40000000-0000-0000-0000-000000000010','40000000-0000-0000-0000-000000000004','manager'),('40000000-0000-0000-0000-000000000020','40000000-0000-0000-0000-000000000003','owner');
set local role authenticated; set local request.jwt.claims='{"sub":"40000000-0000-0000-0000-000000000001"}';
select is((public.read_team_plan('40000000-0000-0000-0000-000000000010',true)->>'version')::bigint,0::bigint,'empty plan starts at version zero');
select is(public.read_team_plan('40000000-0000-0000-0000-000000000010',true)->>'time_zone','Europe/Istanbul','explicit civil timezone');
select is(public.read_team_plan('40000000-0000-0000-0000-000000000010',false)->>'published_version',null,'never published metadata');
select is(public.save_team_shift('40000000-0000-0000-0000-000000000010',0,null,'40000000-0000-0000-0000-000000000002','2026-10-25 22:00','2026-10-26 06:00',60,'Gece','not'),1::bigint,'owner assigns overnight shift');
select public.read_team_plan('40000000-0000-0000-0000-000000000010',true)->'shifts'->0->>'id' as shift_id \gset
select is(jsonb_array_length(public.read_team_plan('40000000-0000-0000-0000-000000000010',true)->'shifts'),1,'draft saved');
select is(jsonb_array_length(public.read_team_plan('40000000-0000-0000-0000-000000000010',false)->'shifts'),0,'draft not published automatically');
select throws_ok($q$select public.save_team_shift('40000000-0000-0000-0000-000000000010',0,null,'40000000-0000-0000-0000-000000000002','2026-10-25 22:00','2026-10-26 06:00',60,'Gece','not')$q$,'40001',null,'stale create rejected');
select throws_ok($q$select public.save_team_shift('40000000-0000-0000-0000-000000000010',1,null,'40000000-0000-0000-0000-000000000002','2026-10-26 05:59','2026-10-26 08:00',60,'Gece','not')$q$,'23P01',null,'previous day overnight overlap rejected');
select is(public.save_team_shift('40000000-0000-0000-0000-000000000010',1,null,'40000000-0000-0000-0000-000000000002','2026-10-26 06:00','2026-10-26 08:00',0,'Gece','not'),2::bigint,'touching boundary allowed');
select throws_ok($q$select public.save_team_shift('40000000-0000-0000-0000-000000000010',2,null,'40000000-0000-0000-0000-000000000002','2026-10-27 08:00','2026-10-27 08:00',0,'Gece','not')$q$,'22023',null,'equal endpoints not 24 hours');
select throws_ok($q$select public.save_team_shift('40000000-0000-0000-0000-000000000010',2,null,'40000000-0000-0000-0000-000000000002','2026-10-27 10:00','2026-10-27 08:00',0,'Gece','not')$q$,'22023',null,'reversed interval rejected');
select throws_ok($q$select public.save_team_shift('40000000-0000-0000-0000-000000000010',2,null,'40000000-0000-0000-0000-000000000002','2026-10-27 08:00','2026-10-27 09:00',-1,'Gece','not')$q$,'22023',null,'negative break rejected');
select throws_ok($q$select public.save_team_shift('40000000-0000-0000-0000-000000000010',2,null,'40000000-0000-0000-0000-000000000002','2026-10-27 08:00','2026-10-27 09:00',61,'Gece','not')$q$,'22023',null,'excess break rejected');
select throws_ok($q$select public.save_team_shift('40000000-0000-0000-0000-000000000010',2,null,'40000000-0000-0000-0000-000000000003','2026-10-25 22:00','2026-10-26 06:00',60,'Gece','not')$q$,'22023',null,'outside assignee rejected');
select is(public.save_team_shift('40000000-0000-0000-0000-000000000010',2,null,'40000000-0000-0000-0000-000000000001','2026-10-25 22:00','2026-10-26 06:00',60,'Gece','not'),3::bigint,'owner can assign self at same time');
select is(public.publish_team_plan('40000000-0000-0000-0000-000000000010',3),4::bigint,'whole team published');
select is((public.read_team_plan('40000000-0000-0000-0000-000000000010',false)->>'published_version')::bigint,4::bigint,'publication version captured');
select is(jsonb_array_length(public.read_team_plan('40000000-0000-0000-0000-000000000010',false)->'shifts'),3,'manager published team snapshot');
select throws_ok($q$select public.publish_team_plan('40000000-0000-0000-0000-000000000010',3)$q$,'40001',null,'stale publication rejected');
select throws_ok(format('select public.delete_team_shift(%L,3,%L)','40000000-0000-0000-0000-000000000010',:'shift_id'),'40001',null,'stale delete rejected');
select is(public.delete_team_shift('40000000-0000-0000-0000-000000000010',4,:'shift_id'),5::bigint,'draft deletion succeeds');
select is(jsonb_array_length(public.read_team_plan('40000000-0000-0000-0000-000000000010',false)->'shifts'),3,'deletion preserves old publication');
set local role authenticated; set local request.jwt.claims='{"sub":"40000000-0000-0000-0000-000000000002"}';
select throws_ok($q$select public.read_team_plan('40000000-0000-0000-0000-000000000010',true)$q$,'42501',null,'employee cannot read drafts');
select is(jsonb_array_length(public.read_team_plan('40000000-0000-0000-0000-000000000010',false)->'shifts'),2,'employee sees only own published shifts');
select ok(not exists(select 1 from jsonb_array_elements(public.read_team_plan('40000000-0000-0000-0000-000000000010',false)->'shifts') s where s->>'user_id'<>'40000000-0000-0000-0000-000000000002'),'no colleague shift leaked');
select throws_ok($q$select public.save_team_shift('40000000-0000-0000-0000-000000000010',5,null,'40000000-0000-0000-0000-000000000001','2026-10-25 22:00','2026-10-26 06:00',60,'Gece','not')$q$,'42501',null,'employee cannot impersonate owner');
select throws_ok($q$select public.publish_team_plan('40000000-0000-0000-0000-000000000010',5)$q$,'42501',null,'employee cannot publish');
select throws_ok(format('select public.delete_team_shift(%L,5,%L)','40000000-0000-0000-0000-000000000010',:'shift_id'),'42501',null,'employee cannot delete');
select throws_ok('select * from public.team_plans','42501',null,'no direct team_plans reads');
select throws_ok('delete from public.team_plans','42501',null,'no direct team_plans writes');
select throws_ok('select * from public.team_shift_drafts','42501',null,'no direct team_shift_drafts reads');
select throws_ok('delete from public.team_shift_drafts','42501',null,'no direct team_shift_drafts writes');
select throws_ok('select * from public.team_shift_published','42501',null,'no direct team_shift_published reads');
select throws_ok('delete from public.team_shift_published','42501',null,'no direct team_shift_published writes');
set local role authenticated; set local request.jwt.claims='{"sub":"40000000-0000-0000-0000-000000000003"}';
select throws_ok($q$select public.read_team_plan('40000000-0000-0000-0000-000000000010',false)$q$,'42501',null,'outsider cannot read publication by team ID');
select throws_ok($q$select public.read_team_plan('40000000-0000-0000-0000-000000000010',true)$q$,'42501',null,'outsider cannot read draft');
select throws_ok($q$select public.save_team_shift('40000000-0000-0000-0000-000000000010',5,null,'40000000-0000-0000-0000-000000000002','2026-10-25 22:00','2026-10-26 06:00',60,'Gece','not')$q$,'42501',null,'outsider cannot write');
select throws_ok($q$select public.publish_team_plan('40000000-0000-0000-0000-000000000010',5)$q$,'42501',null,'outsider cannot publish');
set local role authenticated; set local request.jwt.claims='{"sub":"40000000-0000-0000-0000-000000000004"}';
select is(public.publish_team_plan('40000000-0000-0000-0000-000000000010',5),6::bigint,'manager can republish entire draft');
select is(jsonb_array_length(public.read_team_plan('40000000-0000-0000-0000-000000000010',false)->'shifts'),2,'publication removes deleted shift');
select is(public.save_team_shift('40000000-0000-0000-0000-000000000010',6,null,'40000000-0000-0000-0000-000000000002','2026-10-31 22:00','2026-11-01 06:00',60,'Gece','not'),7::bigint,'month boundary shift accepted');
select is(public.save_team_shift('40000000-0000-0000-0000-000000000010',7,null,'40000000-0000-0000-0000-000000000002','2026-10-28 08:00','2026-10-28 09:00',60,'Gece','not'),8::bigint,'break equal to duration accepted');
select is(public.save_team_shift('40000000-0000-0000-0000-000000000010',8,(public.read_team_plan('40000000-0000-0000-0000-000000000010',true)->'shifts'->0->>'id')::uuid,'40000000-0000-0000-0000-000000000001','2026-10-25 21:00','2026-10-26 06:00',60,'Updated','new note'),9::bigint,'manager can edit assignment');
select is(public.read_team_plan('40000000-0000-0000-0000-000000000010',false)->'shifts'->0->>'label','Gece','edit does not mutate published fields');
select throws_ok($q$select public.publish_team_plan('40000000-0000-0000-0000-000000000010',8)$q$,'40001',null,'edit invalidates pending publication');
set local timezone='America/New_York';
select is(public.read_team_plan('40000000-0000-0000-0000-000000000010',true)->'shifts'->3->>'starts_at','2026-10-31T22:00:00','session timezone cannot shift civil schedule');
reset role;
select is((select (extract(epoch from (least(ends_at,timestamp '2026-11-01')-greatest(starts_at,timestamp '2026-10-01')))/60 * (1-break_minutes*60/extract(epoch from ends_at-starts_at)))::numeric from public.team_shift_drafts where team_id='40000000-0000-0000-0000-000000000010' and starts_at='2026-10-31 22:00'),105::numeric,'October allocation prorates break');
set local role anon;
select throws_ok($q$select public.read_team_plan('40000000-0000-0000-0000-000000000010',false)$q$,'42501',null,'anonymous cannot read');
select throws_ok($q$select public.save_team_shift('40000000-0000-0000-0000-000000000010',8,null,'40000000-0000-0000-0000-000000000002','2026-10-25 22:00','2026-10-26 06:00',60,'Gece','not')$q$,'42501',null,'anonymous cannot assign');
select * from finish();
rollback;
